  [1225475] = { "Riduce di $D1 la durata dell'effetto ⟦Recently Bandaged=Bendato di Recente⟧ quando usi una benda. Inefficace nelle spedizioni, nelle incursioni e nei campi di battaglia.", nil, 0xe07ee097, nil, "um" },
